query UserFreelancerSearch($request: UserFreelancerSearchV2Request!) {
  search {
    universalSearchNuxt {
      userFreelancerSearchV2(request: $request) {
        pagingInfo {
          total
          offset
          count
          originTotal
          pagesTotal
          page
        }
        queryType
        adaptiveSkills {
          id
          prefLabel
          ontologyId
        }

  guidedSpecialties {
    specialties {
      uid: guidedSpecialtyUid
      ontologyId
      label: preferredLabel
    }
  }

        relevantSkillIds
        resultFlags {
          portfolioSearch
        }
        facets {
          hourlyRate {
            key
            value
          }
        }

        profiles {



          individualTotalEarnings
          agencyTotalEarnings
          offerConsultations
          jobSummariesAssignmentRids
          personId
          totalCompletedJobs
          insertionId
          rankInfo {
            d
            iv
          }
          vetted
          profile {
            identity {
              id
              ciphertext
            }
            personAvailability {
              purchasedInvitationBadge {
                active
              }
            }
            personalData {
              title
              firstName
              lastName
              description
              location {
                country
                state
                city
                region
                subregion
                timezone
                zip
              }
              chargeRate {
  rawValue
  currency
}
              portrait {
                portrait100
              }
              profileUrl
            }
            skills {
              ontologySkill {
                id
                preferredLabel
                prettyName
                definition
              }
            }
            projectList {
              totalProjects
              projects {
                id
                title
                projectUrl
                thumbnail
                category
                categoryId
                subCategory
                description
                videoUrl
                public
              }
            }
            verifications {
              idBadgeStatus
              idVerified
            }
            agencies {
              defaultAgencyId
              agencies {
                orgId
                ciphertext
                name
                classifications {
                  id
                  name
                }
                logo
              }
            }
            preferences {
              hideEarnings
              hideJss
            }
            profileAggregates {
              nSS100BwScore
              topRatedStatus
              topRatedPlusStatus
              totalHours
              totalHourlyJobs
              totalEarnings
              totalFixedJobs
            }
            communityCertificates {
              expirationDate
            }
          }
        }
      }
    }
  }
}
